template:
% 参数由系统自动注入：\def\ab{3} \def\bc{4} \def\rightmark{1}
% 视觉归一化：把两直角边中较长的一条缩放到 6 个坐标单位（默认 1 单位 = 1cm，即最长直角边恒约 6cm），保证图形视觉大小稳定；
% 只缩放坐标，线宽、字体、虚线样式保持不变；直角记号尺寸已除以 figscale 补偿，不随归一化缩小。
\pgfmathsetmacro{\figscale}{6 / max(\ab, \bc)}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  % B 为直角顶点，A 在 B 右侧、C 在 B 上方
  \coordinate (B) at (0,0);
  \coordinate (A) at (\ab,0);
  \coordinate (C) at (0,\bc);
  \draw[thick] (A) -- (B) -- (C) -- cycle;
  % 直角记号：小正方形两边（绝对尺寸，已按 figscale 补偿；短边容不下时按边长 20% 收缩）
  \ifnum\rightmark>0
    \pgfmathsetmacro\rm{min(0.3/\figscale, \ab*0.2, \bc*0.2)}
    \draw[thick] (\rm,0) -- (\rm,\rm) -- (0,\rm);
  \fi
  % 顶点标签放边外侧（A 右下、B 左下、C 左上）
  \node[below right=3pt] at (A) {$A$};
  \node[below left=3pt] at (B) {$B$};
  \node[above left=3pt] at (C) {$C$};
\end{tikzpicture}
